package app.dayflow;
import android.util.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
final class FileRecords {interface Visitor{void accept(JSONObject value)throws Exception;}static void visit(File file,Visitor visitor)throws Exception{try(JsonReader reader=new JsonReader(new InputStreamReader(new FileInputStream(file),StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT)))){String format="";int schema=0;boolean records=false;reader.beginObject();while(reader.hasNext()){String key=reader.nextName();if(key.equals("format"))format=reader.nextString();else if(key.equals("schema"))schema=reader.nextInt();else if(key.equals("records")){if(records)throw new IOException("重复records字段");records=true;reader.beginArray();while(reader.hasNext()){Object value=value(reader,0);if(!(value instanceof JSONObject))throw new IOException("无效事项");visitor.accept((JSONObject)value);}reader.endArray();}else reader.skipValue();}reader.endObject();if(reader.peek()!=JsonToken.END_DOCUMENT||!records||!format.equals("dayflow")||schema!=1)throw new IOException("不支持的同步文件格式");}}
 private static Object value(JsonReader r,int depth)throws Exception{if(depth>64)throw new IOException("JSON嵌套过深");switch(r.peek()){case BEGIN_OBJECT:JSONObject object=new JSONObject();r.beginObject();while(r.hasNext()){String key=r.nextName();object.put(key,value(r,depth+1));}r.endObject();return object;case BEGIN_ARRAY:JSONArray array=new JSONArray();r.beginArray();while(r.hasNext())array.put(value(r,depth+1));r.endArray();return array;case STRING:return r.nextString();case NUMBER:return new JSONTokener(r.nextString()).nextValue();case BOOLEAN:return r.nextBoolean();case NULL:r.nextNull();return JSONObject.NULL;default:throw new IOException("无效JSON");}}
}
